SELECT p.supplier,COUNT(DISTINCT p.name) AS invoice_count,SUM(p.net_total) AS net_total,SUM(p.tax_amount) AS tax_amount,SUM(p.grand_total) AS grand_total FROM "tabPurchase Invoice" p WHERE p.docstatus=1 AND (%(company)s='' OR p.company=%(company)s) AND (%(from_date)s='' OR p.posting_date>=%(from_date)s) AND (%(to_date)s='' OR p.posting_date<=%(to_date)s) GROUP BY p.supplier ORDER BY grand_total DESC
